// interactionService.ts
import { InteractionRepository } from '../repositories/interaction.repository';

export class InteractionService {
  constructor(private interactionRepo: InteractionRepository) {}

  async logInteraction(
    userId: string,
    type: 'view' | 'search' | 'favorite' | 'purchase',
    data: any
  ): Promise<void> {
    try {
      const interaction = {
        userId,
        type,
        data,
        timestamp: new Date(),
      };

      // Enregistrement asynchrone en base de données
      await this.interactionRepo.save(interaction);

      // Mise à jour des statistiques en temps réel (optionnel)
      if (type === 'view') {
        await this.updateProductViewCount(data.productId);
      }
    } catch (error) {
      console.error('Erreur lors du logging d\'interaction:', error);
      // Ne pas propager l'erreur pour ne pas bloquer l'utilisateur
    }
  }
}
