async getPersonalizedRecommendations(
  userId: string,
  limit: number = 10
): Promise<Product[]> {
  // 1. Récupérer les IDs des produits favoris de l'utilisateur
  const favoriteProducts = await this.getUserFavorites(userId);

  if (favoriteProducts.length === 0) {
    // 2. Si pas de favoris, recommander les produits populaires
    return this.getPopularProducts(limit);
  }

  // 3. Récupérer les catégories des produits favoris
  const categories = await this.getCategoriesFromProducts(favoriteProducts);

  // 4. Récupérer les produits similaires dans les mêmes catégories
  const recommendations = await this.productRepository
    .createQueryBuilder('product')
    .where('product.categoryId IN (:...categories)', { categories })
    .andWhere('product.id NOT IN (:...favorites)', { 
      favorites: favoriteProducts.map(p => p.id) 
    })
    .orderBy('product.viewCount', 'DESC')
    .limit(limit)
    .getMany();

  // 5. Si pas assez de résultats, compléter avec des produits populaires
  if (recommendations.length < limit) {
    const popular = await this.getPopularProducts(limit - recommendations.length);
    recommendations.push(...popular);
  }

  return recommendations;
}
