// recommendationStore.ts
import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface RecommendationState {
  recommendations: Product[];
  cacheTimestamp: number | null;
  isLoading: boolean;
  error: string | null;

  // Actions
  setRecommendations: (products: Product[]) => void;
  clearCache: () => void;
  isCacheValid: () => boolean;
  getRecommendations: () => Promise<Product[]>;
  invalidateCache: () => void;
}

const TTL = 5 * 60 * 1000; // 5 minutes en millisecondes

export const useRecommendationStore = create<RecommendationState>()(
  persist(
    (set, get) => ({
      recommendations: [],
      cacheTimestamp: null,
      isLoading: false,
      error: null,

      setRecommendations: (products) => 
        set({ 
          recommendations: products, 
          cacheTimestamp: Date.now(),
          isLoading: false,
          error: null
        }),

      clearCache: () => 
        set({ 
          recommendations: [], 
          cacheTimestamp: null 
        }),

      isCacheValid: () => {
        const { cacheTimestamp } = get();
        if (!cacheTimestamp) return false;
        return (Date.now() - cacheTimestamp) < TTL;
      },

      getRecommendations: async () => {
        const { isCacheValid, recommendations, setRecommendations } = get();

        // Si le cache est valide, retourner les données en cache
        if (isCacheValid() && recommendations.length > 0) {
          return recommendations;
        }

        // Sinon, charger les données fraîches
        set({ isLoading: true, error: null });
        try {
          const response = await recommendationService.fetchPersonalized();
          setRecommendations(response);
          return response;
        } catch (error) {
          set({ 
            error: error.message, 
            isLoading: false 
          });
          // Retourner les données en cache même si expirées
          return recommendations;
        }
      },

      invalidateCache: () => {
        set({ cacheTimestamp: null });
      }
    }),
    {
      name: 'recommendation-store', // Persistance dans AsyncStorage
    }
  )
);
