// RecommendationSection.tsx
import React from 'react';
import { View, Text, FlatList, ActivityIndicator, TouchableOpacity, StyleSheet } from 'react-native';
import { useRecommendationStore } from '../stores/recommendationStore';
import { ProductCard } from './ProductCard';

export const RecommendationSection = () => {
  const { 
    recommendations, 
    isLoading, 
    error, 
    getRecommendations 
  } = useRecommendationStore();

  const loadRecommendations = async () => {
    await getRecommendations();
  };

  // 1. État de chargement
  if (isLoading && recommendations.length === 0) {
    return (
      <View style={styles.container}>
        <Text style={styles.title}>Recommandations pour vous</Text>
        <View style={styles.loaderContainer}>
          <ActivityIndicator size="large" color="#48bb78" />
          <Text style={styles.loadingText}>Chargement des recommandations...</Text>
        </View>
      </View>
    );
  }

  // 2. État d'erreur
  if (error && recommendations.length === 0) {
    return (
      <View style={styles.container}>
        <Text style={styles.title}>Recommandations pour vous</Text>
        <View style={styles.errorContainer}>
          <Text style={styles.errorIcon}>😕</Text>
          <Text style={styles.errorText}>{error}</Text>
          <TouchableOpacity style={styles.retryButton} onPress={loadRecommendations}>
            <Text style={styles.retryText}>Réessayer</Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }

  // 3. État de succès
  if (recommendations.length === 0) {
    return (
      <View style={styles.container}>
        <Text style={styles.title}>Recommandations pour vous</Text>
        <View style={styles.emptyContainer}>
          <Text style={styles.emptyText}>Aucune recommandation disponible</Text>
          <Text style={styles.emptySubtext}>Explorez notre catalogue pour découvrir des produits.</Text>
        </View>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>🔥 Recommandations pour vous</Text>
        {isLoading && <ActivityIndicator size="small" color="#48bb78" />}
      </View>
      <FlatList
        horizontal
        showsHorizontalScrollIndicator={false}
        data={recommendations}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <ProductCard product={item} variant="horizontal" />
        )}
        contentContainerStyle={styles.listContent}
      />
    </View>
  );
};
